-- changed on re-run and community stories are never touched. Nothing is deleted.
-- Run supabase/tests/world_seed_check.sql afterwards.
-- =============================================================================

begin;

insert into public.destinations
  (slug, name, region, country, description, latitude, longitude, status, is_demo)
values
  ('paris', 'Paris', 'Île-de-France', 'France', 'France''s capital, known for its museums, cafés and riverside walks along the Seine.', 48.8566, 2.3522, 'published', false),
  ('rome', 'Rome', 'Lazio', 'Italy', 'The Italian capital, layered with ancient ruins, churches and piazzas.', 41.9028, 12.4964, 'published', false),
  ('venice', 'Venice', 'Veneto', 'Italy', 'A lagoon city of canals and bridges, with no cars at all.', 45.4408, 12.3155, 'published', false),
  ('barcelona', 'Barcelona', 'Catalonia', 'Spain', 'A Mediterranean city known for Gaudí''s architecture and its beaches.', 41.3874, 2.1686, 'published', false),
  ('amsterdam', 'Amsterdam', 'North Holland', 'Netherlands', 'A canal city of narrow houses, museums and bicycles.', 52.3676, 4.9041, 'published', false),
  ('london', 'London', 'England', 'United Kingdom', 'The UK capital, with free museums, royal parks and a huge Underground network.', 51.5074, -0.1278, 'published', false),
  ('edinburgh', 'Edinburgh', 'Scotland', 'United Kingdom', 'Scotland''s hilly capital, with a castle above the medieval Old Town.', 55.9533, -3.1883, 'published', false),
  ('santorini', 'Santorini (Oia)', 'South Aegean', 'Greece', 'A volcanic Cycladic island of white villages on a caldera cliff.', 36.4618, 25.3753, 'published', false),
  ('zermatt', 'Zermatt', 'Valais', 'Switzerland', 'A car-free Alpine village beneath the Matterhorn.', 46.0207, 7.7491, 'published', false),
  ('reykjavik', 'Reykjavík', 'Capital Region', 'Iceland', 'Iceland''s capital and the starting point for most road trips.', 64.1466, -21.9426, 'published', false),
  ('vik', 'Vík', 'South Iceland', 'Iceland', 'A small village on Iceland''s south coast, near the black-sand beach at Reynisfjara.', 63.4186, -19.006, 'published', false),
  ('prague', 'Prague', 'Prague', 'Czechia', 'The Czech capital, with a medieval centre, bridges and a hilltop castle.', 50.0755, 14.4378, 'published', false),
  ('lisbon', 'Lisbon', 'Lisbon District', 'Portugal', 'Portugal''s hilly capital on the Tagus, known for trams and viewpoints.', 38.7223, -9.1393, 'published', false),
  ('istanbul', 'Istanbul', 'Istanbul Province', 'Türkiye', 'A city on two continents, known for its mosques, bazaars and the Bosphorus.', 41.0082, 28.9784, 'published', false),
  ('dubrovnik', 'Dubrovnik', 'Dubrovnik-Neretva', 'Croatia', 'A walled Adriatic city of limestone streets and terracotta roofs.', 42.6507, 18.0944, 'published', false),
  ('tromso', 'Tromsø', 'Troms', 'Norway', 'An Arctic city that''s a base for northern lights and polar night trips.', 69.6492, 18.9553, 'published', false),
  ('kyoto', 'Kyoto', 'Kyoto Prefecture', 'Japan', 'Japan''s former imperial capital, with temples, shrines and traditional districts.', 35.0116, 135.7681, 'published', false),
  ('tokyo', 'Tokyo', 'Tokyo', 'Japan', 'Japan''s capital, a huge city linked by an efficient rail network.', 35.6762, 139.6503, 'published', false),
  ('bangkok', 'Bangkok', 'Bangkok', 'Thailand', 'Thailand''s capital, known for temples, street food and river boats.', 13.7563, 100.5018, 'published', false),
  ('chiang-mai', 'Chiang Mai', 'Chiang Mai Province', 'Thailand', 'Northern Thailand''s main city, ringed by mountains and temples.', 18.7883, 98.9853, 'published', false),
  ('ubud', 'Ubud', 'Bali', 'Indonesia', 'Bali''s inland cultural town of rice terraces, temples and craft villages.', -8.5069, 115.2625, 'published', false),
  ('hanoi', 'Hanoi', 'Hanoi', 'Vietnam', 'Vietnam''s capital, with a busy Old Quarter and lakes.', 21.0278, 105.8342, 'published', false),
  ('ha-long-bay', 'Ha Long Bay', 'Quảng Ninh', 'Vietnam', 'A bay of limestone islands, usually explored by boat.', 20.9101, 107.1839, 'published', false),
  ('siem-reap', 'Siem Reap (Angkor)', 'Siem Reap Province', 'Cambodia', 'The town beside the Angkor temples, including Angkor Wat.', 13.3633, 103.8564, 'published', false),
  ('kathmandu', 'Kathmandu', 'Bagmati Province', 'Nepal', 'Nepal''s capital, with medieval squares and the starting point for many treks.', 27.7172, 85.324, 'published', false),
  ('lukla', 'Lukla', 'Koshi Province', 'Nepal', 'A mountain airstrip village and the usual gateway to the Everest region.', 27.687, 86.7314, 'published', false),
  ('seoul', 'Seoul', 'Seoul', 'South Korea', 'South Korea''s capital, mixing palaces, markets and neon districts.', 37.5665, 126.978, 'published', false),
  ('singapore', 'Singapore', 'Singapore', 'Singapore', 'A city-state known for food centres, gardens and an efficient MRT.', 1.3521, 103.8198, 'published', false),
  ('maafushi', 'Maafushi', 'Kaafu Atoll', 'Maldives', 'A local island south of Malé, popular for guesthouse stays.', 3.9431, 73.4906, 'published', false),
  ('ella', 'Ella', 'Uva Province', 'Sri Lanka', 'A hill-country village of tea estates, walks and the Nine Arches Bridge.', 6.8667, 81.0466, 'published', false),
  ('dubai', 'Dubai', 'Dubai', 'United Arab Emirates', 'A Gulf city of skyscrapers, desert trips and old souks along the creek.', 25.2048, 55.2708, 'published', false),
  ('petra', 'Petra', 'Ma''an Governorate', 'Jordan', 'An ancient Nabataean city carved into rose-coloured rock.', 30.3285, 35.4444, 'published', false),
  ('beijing', 'Beijing', 'Beijing', 'China', 'China''s capital, home to the Forbidden City and nearby sections of the Great Wall.', 39.9042, 116.4074, 'published', false),
  ('new-york-city', 'New York City', 'New York', 'United States', 'A city of five boroughs, museums, parks and a 24-hour subway.', 40.7128, -74.006, 'published', false),
  ('grand-canyon-south-rim', 'Grand Canyon (South Rim)', 'Arizona', 'United States', 'The most visited rim of the Grand Canyon, with viewpoints and steep trails down.', 36.0544, -112.1401, 'published', false),
  ('yosemite-valley', 'Yosemite Valley', 'California', 'United States', 'A glacier-carved valley of granite walls and waterfalls in Yosemite National Park.', 37.7456, -119.5936, 'published', false),
  ('banff', 'Banff', 'Alberta', 'Canada', 'A mountain town in Banff National Park, near turquoise lakes such as Moraine and Louise.', 51.1784, -115.5708, 'published', false),
  ('mexico-city', 'Mexico City', 'Mexico City', 'Mexico', 'Mexico''s high-altitude capital, with museums, markets and Aztec ruins nearby.', 19.4326, -99.1332, 'published', false),
  ('cusco', 'Cusco', 'Cusco Region', 'Peru', 'The old Inca capital, high in the Andes and the gateway to Machu Picchu.', -13.532, -71.9675, 'published', false),
  ('machu-picchu', 'Machu Picchu', 'Cusco Region', 'Peru', 'The Inca citadel above the Urubamba valley, reached via Aguas Calientes.', -13.1631, -72.545, 'published', false),
  ('rio-de-janeiro', 'Rio de Janeiro', 'Rio de Janeiro State', 'Brazil', 'A coastal city between mountains and beaches, overlooked by Christ the Redeemer.', -22.9068, -43.1729, 'published', false),
  ('el-chalten', 'El Chaltén', 'Santa Cruz', 'Argentina', 'A small Patagonian trekking village below Mount Fitz Roy.', -49.3315, -72.8863, 'published', false),
  ('torres-del-paine', 'Torres del Paine', 'Magallanes', 'Chile', 'A Patagonian national park famous for its granite towers and the W trek.', -50.9423, -73.4068, 'published', false),
  ('galapagos', 'Galápagos (Puerto Ayora)', 'Galápagos Province', 'Ecuador', 'Puerto Ayora, on Santa Cruz Island, is the main town of the Galápagos.', -0.7432, -90.3138, 'published', false),
  ('monteverde', 'Monteverde', 'Puntarenas', 'Costa Rica', 'A cloud-forest town known for hanging bridges and wildlife.', 10.3009, -84.8254, 'published', false),
  ('marrakech', 'Marrakech', 'Marrakech-Safi', 'Morocco', 'A red-walled city known for its medina, souks and Jemaa el-Fna square.', 31.6295, -7.9811, 'published', false),
  ('cairo', 'Cairo', 'Cairo Governorate', 'Egypt', 'Egypt''s capital, beside the Giza pyramids.', 30.0444, 31.2357, 'published', false),
  ('cape-town', 'Cape Town', 'Western Cape', 'South Africa', 'A coastal city beneath Table Mountain.', -33.9249, 18.4241, 'published', false),
  ('serengeti', 'Serengeti', 'Mara Region', 'Tanzania', 'A vast savannah national park known for the great wildebeest migration.', -2.3333, 34.8333, 'published', false),
  ('stone-town', 'Stone Town', 'Zanzibar', 'Tanzania', 'The historic centre of Zanzibar City, with winding lanes and carved doors.', -6.1659, 39.2026, 'published', false),
  ('victoria-falls', 'Victoria Falls', 'Matabeleland North', 'Zimbabwe', 'The town beside the Victoria Falls on the Zambezi.', -17.9243, 25.8572, 'published', false),
  ('sydney', 'Sydney', 'New South Wales', 'Australia', 'A harbour city known for its beaches, ferries and Opera House.', -33.8688, 151.2093, 'published', false),
  ('cairns', 'Cairns', 'Queensland', 'Australia', 'A tropical city and gateway to the Great Barrier Reef.', -16.9186, 145.7781, 'published', false),
  ('uluru', 'Uluru', 'Northern Territory', 'Australia', 'A sacred sandstone monolith in Uluṟu-Kata Tjuṯa National Park.', -25.3444, 131.0369, 'published', false),
  ('queenstown', 'Queenstown', 'Otago', 'New Zealand', 'A lakeside adventure town in the Southern Alps.', -45.0312, 168.6626, 'published', false)
on conflict (slug) do nothing;

insert into public.stories as s
  (id, destination_id, title, body, category, place_name, latitude, longitude,
   travel_month, challenge, lesson, advice, status, published_at, is_demo, source)
select v.id::uuid, d.id, v.title, v.body, v.category, v.place_name, v.latitude, v.longitude,
       v.travel_month::smallint, v.challenge, v.lesson, v.advice,
       'published', now() - make_interval(mins => v.ord), false, 'editorial'
from (values
  ('d4ccbccf-187a-5dd3-bd8c-8b474420eb1a', 'paris/museum-closing-days', 'paris', 'Big museums take different days off', 'The Louvre closes on Tuesdays, while the Musée d''Orsay closes on Mondays. A short trip that leaves both for the start of the week can lose one of them entirely.', 'planning', 'Louvre Museum', 48.8606, 2.3376, null, null, 'Check each museum''s closing day before you fix the order of your days.', 'Timed tickets booked online usually mean a much shorter wait at the entrance.', 1),
  ('d7d5ae6c-51a7-5a1a-9c88-d4601e2ed96a', 'rome/vatican-sunday', 'rome', 'The Vatican Museums are closed most Sundays', 'The Vatican Museums close on Sundays, apart from a free-entry last Sunday of the month that draws enormous queues. A Sunday plan for the Sistine Chapel rarely works out.', 'planning', 'Vatican Museums', 41.9065, 12.4536, null, null, 'Book a weekday slot online, ideally first thing in the morning.', null, 2),
  ('cf7aebf7-cd97-5527-a604-9b44e5f0b006', 'barcelona/sagrada-familia', 'barcelona', 'Sagrada Família tickets sell out days ahead', 'Entry to the Sagrada Família is by timed ticket, and tower visits are limited. In busy months, same-day tickets are often gone.', 'planning', 'Sagrada Família', 41.4036, 2.1744, null, null, 'Book online as soon as your dates are fixed.', null, 3),
  ('ea5b23cc-d418-5112-bcb6-8098a8208ab9', 'amsterdam/anne-frank-tickets', 'amsterdam', 'Anne Frank House tickets are online only', 'Tickets for the Anne Frank House are sold online for set time slots, not at the door. They''re released in advance and go quickly.', 'planning', 'Anne Frank House', 52.3752, 4.884, null, null, 'Book as soon as tickets are released for your dates.', null, 4),
  ('c3a305eb-8b00-5f67-aab1-2a6005f00b40', 'london/contactless', 'london', 'Tap a contactless card instead of buying tickets', 'Contactless bank cards and phones work at Underground and bus readers, with daily fare caps. Paper single tickets usually cost more.', 'costs', 'London Underground', 51.5154, -0.1755, null, null, 'Use one contactless card per person and always tap out.', null, 5),
  ('ecba4780-ca32-5c2a-9645-3afc113e0fe1', 'santorini/oia-sunset', 'santorini', 'Oia''s sunset spot fills up early', 'The best-known sunset viewpoint in Oia gets packed well before the sun goes down, and the lanes jam afterwards.', 'planning', 'Oia castle viewpoint', 36.4612, 25.3725, null, null, 'Arrive early, or watch the sunset from a quieter spot along the caldera.', null, 6),
  ('1cb84b27-7567-5fd5-afa0-a5497db1170c', 'zermatt/car-free', 'zermatt', 'You can''t drive into Zermatt', 'Zermatt is car-free. Drivers park in Täsch and take the shuttle train for the last stretch into the village.', 'transport', 'Täsch station', 46.0688, 7.7776, null, null, 'Plan to leave the car at Täsch and travel up by train.', null, 7),
  ('398e370a-7be6-52c7-8c5c-bc6040a1fc2f', 'reykjavik/f-roads', 'reykjavik', 'Highland F-roads need the right car and season', 'Iceland''s highland F-roads are open only in summer and require a 4x4. Rental agreements often exclude them for ordinary cars.', 'transport', 'Reykjavík', 64.1466, -21.9426, null, null, 'Check road status on the official road website and your rental terms before planning a highland route.', null, 8),
  ('a58476f7-7c2e-5e69-98ba-5e9664d837c6', 'prague/currency', 'prague', 'Czechia uses its own currency', 'Czechia uses the koruna, not the euro. Some street exchange offices advertise attractive rates that turn out to apply only to large amounts.', 'costs', 'Old Town Square', 50.0875, 14.4213, null, null, 'Use a bank ATM or card where possible, and read exchange terms carefully.', null, 9),
  ('bd0bb472-819a-5f1b-bf20-8b3c18e90f90', 'lisbon/slippery-hills', 'lisbon', 'Polished pavements get slippery', 'Lisbon''s steep streets are paved with smooth limestone cobbles that become slick, especially after rain.', 'packing', 'Alfama', 38.7114, -9.1302, null, null, 'Wear shoes with real grip rather than smooth-soled sandals.', null, 10),
  ('4e2a3403-cd68-5bde-b69e-fcf7f4d7f8b8', 'istanbul/prayer-times', 'istanbul', 'Mosques pause visits at prayer times', 'Working mosques close to visitors during the five daily prayers, most noticeably at Friday midday prayers. Women are asked to cover their hair, and everyone should cover shoulders and knees.', 'local_customs', 'Blue Mosque', 41.0054, 28.9768, null, null, 'Check prayer times and carry a scarf.', null, 11),
  ('15715f26-7c54-5ce5-8ba7-744bbdba3eee', 'dubrovnik/walls-heat', 'dubrovnik', 'Walk the walls early', 'The city walls loop has little shade, and the stone radiates heat by midday in summer. Cruise passengers also arrive mid-morning.', 'weather', 'City walls', 42.6417, 18.1077, null, null, 'Start the walls walk when it opens, with water and a hat.', null, 12),
  ('04d4ebe9-06f9-5f2c-9361-ef16408cc9c9', 'tromso/aurora', 'tromso', 'The northern lights aren''t guaranteed', 'Aurora sightings depend on clear skies and solar activity. Cloudy nights are common, even in the best season.', 'weather', 'Tromsø', 69.6492, 18.9553, null, null, 'Stay several nights and keep evenings flexible.', null, 13),
  ('029b89f0-68d4-5134-bdd0-72888fc2ac9a', 'kyoto/fushimi-inari-early', 'kyoto', 'Fushimi Inari is a different place at dawn', 'By mid-morning the lower torii gates are packed. Early in the morning, or higher up the mountain, the paths are much quieter.', 'planning', 'Fushimi Inari Taisha', 34.9671, 135.7727, null, null, 'Go early and keep walking past the first crowded section.', null, 14),
  ('b7726324-2b2f-5659-a883-71182ac5c984', 'bangkok/grand-palace-dress', 'bangkok', 'The Grand Palace has a strict dress code', 'Visitors to the Grand Palace and major temples need covered shoulders and knees. People in shorts or sleeveless tops are turned away or asked to cover up.', 'local_customs', 'Grand Palace', 13.75, 100.4913, null, null, 'Dress for the temple dress code on palace days.', null, 15),
  ('0db02315-d471-57d3-a29f-391775a3a7bb', 'ubud/tourist-levy', 'ubud', 'Bali charges a tourist levy', 'International visitors to Bali pay a tourist levy, separate from any visa fee. It can be paid online before arrival.', 'costs', 'Ubud', -8.5069, 115.2625, null, null, 'Pay through the official channel and keep the confirmation.', null, 16),
  ('d5eb479a-ae58-54e7-8e5b-0b33a8086934', 'hanoi/crossing', 'hanoi', 'Cross the road slowly and steadily', 'Hanoi''s streets are full of motorbikes that rarely stop. Riders steer around pedestrians who move at a predictable pace; sudden stops and dashes are what cause trouble.', 'safety', 'Old Quarter', 21.0341, 105.85, null, null, 'Walk at a steady pace and don''t run.', null, 17),
  ('f982a3fa-29c6-51f7-893f-45a26ffd3d17', 'siem-reap/angkor-pass', 'siem-reap', 'Buy the Angkor pass before the temples', 'Entry to the Angkor temples requires an Angkor Pass, sold for one or several days. Passes are checked at the main temples.', 'planning', 'Angkor ticket centre', 13.3743, 103.8762, null, null, 'Decide how many days you need and buy the matching pass.', null, 18),
  ('eea9debb-822e-570a-abc8-5cdae99530f1', 'kathmandu/stupa-kora', 'kathmandu', 'Walk clockwise around Boudhanath', 'At Boudhanath and other Buddhist stupas, people circle clockwise and spin prayer wheels as they pass.', 'local_customs', 'Boudhanath Stupa', 27.7215, 85.362, null, null, 'Follow the clockwise flow around stupas.', null, 19),
  ('fd167c3b-9bf9-5c3f-a5b6-a6a0d8e5f9b4', 'seoul/maps', 'seoul', 'Use local map apps for directions', 'Walking and driving directions in global map apps are limited in South Korea. Local apps such as Naver Map or KakaoMap give much better routes.', 'transport', 'Myeong-dong', 37.5637, 126.9838, null, null, 'Download a local map app before you arrive.', null, 20),
  ('15903578-6eaf-5db1-b995-740bb19e7202', 'singapore/mrt-rules', 'singapore', 'No eating or drinking on the MRT', 'Eating and drinking are not allowed on Singapore''s trains and in paid station areas, and fines can apply.', 'local_customs', 'City Hall MRT', 1.2931, 103.852, null, null, 'Finish your snack before you tap in.', null, 21),
  ('a6c897d5-7cf4-55a2-9bab-323ac87fa621', 'maafushi/local-island-rules', 'maafushi', 'Local islands follow local rules', 'On inhabited local islands alcohol isn''t sold and modest dress is expected away from designated bikini beaches. Resorts on private islands have different rules.', 'local_customs', 'Maafushi', 3.9431, 73.4906, null, null, 'Pick between a local island and a resort knowing which rules apply.', null, 22),
  ('53ef8d08-66b9-55c5-8227-644eae5a85dd', 'ella/train-seats', 'ella', 'Reserved seats on the hill-country train go fast', 'The scenic train between Kandy and Ella is popular, and reserved seats sell out early. Unreserved carriages can be very crowded.', 'transport', 'Ella railway station', 6.8761, 81.0485, null, null, 'Book reserved seats as soon as they open, or be ready to stand.', null, 23),
  ('9a4b483d-ff12-56a0-8d91-f5727abced1f', 'dubai/summer-heat', 'dubai', 'Summer days are extremely hot', 'From late spring to early autumn, daytime heat in Dubai is intense. Walking between sights at midday can be exhausting and unsafe.', 'weather', 'Dubai Creek', 25.2637, 55.3001, null, null, 'Plan outdoor sightseeing for early morning and evening.', null, 24),
  ('25eb54e6-7794-52cd-be83-d476600fb33c', 'petra/walking', 'petra', 'Petra is a long day on foot', 'From the visitor centre, the walk through the Siq to the Treasury is just the start. The climb to the Monastery is hundreds of steps on top of that.', 'activity', 'The Monastery (Ad Deir)', 30.3384, 35.4316, null, null, 'Start early, carry water, and consider a two-day ticket.', null, 25),
  ('0898aa4c-ab78-50c7-a6ec-970759e06c36', 'beijing/forbidden-city', 'beijing', 'The Forbidden City needs a booked, named ticket', 'Tickets for the Palace Museum are booked in advance and tied to your passport, with a daily cap. It closes on Mondays outside national holidays.', 'planning', 'Palace Museum (Forbidden City)', 39.9163, 116.3972, null, null, 'Book ahead and carry the passport you booked with.', null, 26),
  ('65cee96a-43d7-5f89-93ce-ce364603e33e', 'new-york-city/express-local', 'new-york-city', 'Express trains skip stops', 'Many subway lines run both express and local trains on the same platform. Boarding an express can carry you far past a small station.', 'transport', 'Times Square–42nd Street', 40.7553, -73.987, null, null, 'Check whether your stop is served by express or local trains before you board.', null, 27),
  ('b7b3b12e-b8db-5d07-bebc-fcfd4620b7da', 'banff/moraine-shuttle', 'banff', 'You can''t drive your own car to Moraine Lake', 'The road to Moraine Lake is closed to private vehicles. Visitors use Parks Canada shuttles or licensed commercial buses, which are often booked ahead.', 'transport', 'Moraine Lake', 51.3217, -116.186, null, null, 'Reserve a shuttle seat early, especially for sunrise.', null, 28),
  ('f5db1a03-a6c7-529c-9723-61f79c67dead', 'mexico-city/altitude', 'mexico-city', 'The city sits at about 2,240 m', 'Mexico City''s altitude can leave visitors short of breath and tired for the first day or two, especially climbing pyramids nearby.', 'activity', 'Zócalo', 19.4326, -99.1332, null, null, 'Take the first day easy and drink plenty of water.', null, 29),
  ('c30dc05d-2b00-55e3-9bb7-525891f273d0', 'cusco/altitude', 'cusco', 'Arrive slowly; Cusco is high', 'Cusco is at about 3,400 m. Flying in and starting a long walking day straight away is a common recipe for altitude sickness.', 'activity', 'Plaza de Armas', -13.5167, -71.9787, null, null, 'Rest on arrival, or start in the lower Sacred Valley and go up later.', null, 30),
  ('91de49c4-dc60-56e8-9ee5-ff01c5422e3b', 'rio-de-janeiro/clouds', 'rio-de-janeiro', 'Check the clouds before going up Corcovado', 'The statue on Corcovado is often wrapped in cloud, and on those days there''s little view from the top.', 'weather', 'Christ the Redeemer', -22.9519, -43.2105, null, null, 'Look at live webcams or the sky that morning and keep the visit flexible.', null, 31),
  ('4c9169c2-bb56-55b1-a6d8-ef74657c2b4d', 'el-chalten/wind', 'el-chalten', 'Patagonian wind is serious', 'Strong gusts are common around El Chaltén, especially on exposed ridges. The final climb to Laguna de los Tres can be tough in bad weather.', 'weather', 'Laguna de los Tres trail', -49.2715, -73.0434, null, null, 'Check the forecast and turn back on exposed sections if the wind picks up.', null, 32),
  ('962802db-8d40-522a-b148-067138e7fcdf', 'torres-del-paine/campsite-bookings', 'torres-del-paine', 'Campsites on the W trek must be booked', 'Overnight stays on the park''s main trekking routes require campsite or refugio reservations in advance. Rangers check bookings.', 'planning', 'Torres del Paine', -50.9423, -73.4068, null, null, 'Book every night of the route before you arrive.', null, 33),
  ('050d254a-73a1-5142-a8f5-9bf2c221ba8e', 'galapagos/fees', 'galapagos', 'Entry involves fees and a transit card', 'Visitors to the Galápagos pay a national park entrance fee and need a transit control card on arrival. The amounts have changed in recent years.', 'costs', 'Puerto Ayora', -0.7432, -90.3138, null, null, 'Check the current official fees and bring cash for payments on arrival.', null, 34),
  ('0db2ffc7-dc08-5d67-9001-8033ee890863', 'monteverde/cool-wet', 'monteverde', 'The cloud forest is cool and damp', 'Monteverde sits high in the mountains and is often misty, windy and cooler than the beaches. Trails can be muddy.', 'packing', 'Monteverde Cloud Forest Reserve', 10.3021, -84.7951, null, null, 'Bring a rain jacket, a warm layer and shoes that can get wet.', null, 35),
  ('95eb40a2-4376-5e42-a7f4-ebc1263bfd74', 'marrakech/medina-maze', 'marrakech', 'The medina is easy to get lost in', 'The medina''s lanes twist and change names, and map apps can be unreliable inside. Offers of directions sometimes come with an expectation of payment.', 'transport', 'Medina', 31.6295, -7.9878, null, null, 'Download an offline map and note big landmarks to navigate by.', null, 36),
  ('c3011732-4def-590d-b66e-f30d9b5b097c', 'cairo/giza-heat', 'cairo', 'Visit Giza early', 'The Giza plateau is open desert with little shade. By midday it''s hot and much busier.', 'weather', 'Giza pyramids', 29.9792, 31.1342, null, null, 'Arrive at opening time with water and sun protection.', null, 37),
  ('1e43b371-69ee-5c2c-ac8b-c3601f18b7b1', 'cape-town/cableway-wind', 'cape-town', 'The Table Mountain cableway stops in wind', 'The cableway closes when it''s too windy or cloudy, which happens often. A clear morning can turn into a closure by afternoon.', 'weather', 'Table Mountain Aerial Cableway', -33.948, 18.4031, null, null, 'Go on the first clear day rather than saving it for later.', null, 38),
  ('311fde36-b5b1-536b-a342-21bbefae609c', 'serengeti/migration-moves', 'serengeti', 'The migration moves through the year', 'The wildebeest herds move around the Serengeti ecosystem with the seasons. Where you stay determines what you''ll see.', 'planning', 'Serengeti National Park', -2.3333, 34.8333, null, null, 'Match your camp''s location to the month you travel.', null, 39),
  ('85411928-1466-596d-accf-a934f7e91187', 'victoria-falls/spray', 'victoria-falls', 'High water means you''ll get soaked', 'In the high-water months the spray is so heavy that you get drenched and the falls can be hard to see. In the dry season the flow drops a lot on some sections.', 'weather', 'Victoria Falls rainforest', -17.9244, 25.8569, null, null, 'Choose your month for the experience you want, and bring a raincoat in high water.', null, 40),
  ('22c6a61d-0e83-57c3-be72-52cf8e923e6a', 'sydney/flags', 'sydney', 'Swim between the flags', 'Patrolled beaches mark the supervised area with red and yellow flags. Rip currents can be strong outside them.', 'safety', 'Bondi Beach', -33.8915, 151.2767, null, null, 'Swim only between the flags and follow lifeguard instructions.', null, 41),
  ('33900981-1476-55dd-8f6f-1389dce820f7', 'queenstown/milford-road', 'queenstown', 'Milford Sound is a very long day from Queenstown', 'The road to Milford Sound is long and winding, and it can close for snow or avalanche risk in winter.', 'transport', 'Milford Road', -44.9, 168.1, null, null, 'Stay in Te Anau or take a coach or flight, and check the road status first.', null, 42),
  ('c471e635-ea4f-521e-8009-3fbcd6461861', 'paris/metro-bags', 'paris', 'Keep your bag zipped on crowded metro lines', 'Busy metro lines and big interchange stations are where pickpocketing is most common. Phones in back pockets and open tote bags are the easy targets.', 'safety', 'Châtelet–Les Halles', 48.8619, 2.3469, null, null, 'Carry a bag that closes and keep your phone in a front pocket in crowds.', null, 43),
  ('e8e8b9b8-3f6d-5f50-ad7e-12f851aa5cd2', 'rome/church-dress', 'rome', 'Cover shoulders and knees for churches', 'St Peter''s and many Roman churches turn away visitors in shorts, short skirts or bare shoulders. Summer outfits that are fine for the Forum aren''t fine inside.', 'local_customs', 'St Peter''s Basilica', 41.9022, 12.4539, null, null, 'Carry a light scarf or wear clothes that cover shoulders and knees on church days.', null, 44),
  ('017cde61-c78d-569f-b102-78f27b4fefdc', 'barcelona/park-guell', 'barcelona', 'Park Güell''s famous part is ticketed', 'The mosaic terrace and dragon at Park Güell are inside a paid, timed-entry zone. Walking up the hill without a ticket gets you the outer park only.', 'costs', 'Park Güell', 41.4145, 2.1527, null, null, 'Reserve a slot for the monumental zone before you climb up.', null, 45),
  ('ed8966ba-e7d5-556e-ab26-8541129c8da1', 'amsterdam/bike-lanes', 'amsterdam', 'Red paths are for bikes, not people', 'Amsterdam''s reddish paths are cycle lanes, and riders move fast and expect them to be clear. Stepping out to take a canal photo is a common near-miss.', 'safety', 'Canal ring', 52.3702, 4.8852, null, null, 'Look both ways for bikes, and stay on the pavement when you stop.', null, 46),
  ('f0fc691a-232d-529f-9f61-bfe29aa330a4', 'london/escalators', 'london', 'Stand on the right on escalators', 'On Tube escalators people stand on the right and walk on the left. Blocking the left side at rush hour attracts a lot of sighs.', 'local_customs', 'Underground escalators', 51.5074, -0.1278, null, null, 'Keep right when standing, especially with luggage.', null, 47),
  ('5ffee1bc-a012-5d5b-8453-4094138beb8c', 'santorini/cruise-days', 'santorini', 'Cruise ship days change the island', 'When several cruise ships are in, Fira''s paths and the cable car get very crowded during the day.', 'planning', 'Fira', 36.4167, 25.4318, null, null, 'Check the cruise schedule and plan town visits for the early morning or evening.', null, 48),
  ('3cf478d7-cc17-5cb9-a783-0bc4823c0e47', 'zermatt/matterhorn-clouds', 'zermatt', 'The Matterhorn hides in cloud', 'Clouds often wrap the Matterhorn, especially in the afternoon. A single-day visit can end without a clear view at all.', 'weather', 'Gornergrat', 45.9837, 7.7845, null, null, 'Check the mountain webcams before buying lift tickets, and go up early.', null, 49),
  ('0d1afa19-b8e7-543f-97f0-c532592a8170', 'vik/sneaker-waves', 'vik', 'Keep well back from the waves at Reynisfjara', 'Reynisfjara is known for sudden, powerful sneaker waves that run much further up the beach than the others. Warning signs and light systems explain the risk.', 'safety', 'Reynisfjara beach', 63.4044, -19.0447, null, null, 'Never turn your back on the sea there, and follow the warning signs.', null, 50),
  ('58cfd9c2-9e9c-503d-a81a-dffb83e06e3d', 'prague/charles-bridge', 'prague', 'Charles Bridge is calm only at dawn', 'By mid-morning Charles Bridge is shoulder to shoulder with visitors and stalls. Early morning is the time for photos.', 'planning', 'Charles Bridge', 50.0865, 14.4114, null, null, 'Cross at sunrise, then save the castle for later in the day.', null, 51),
  ('30b78350-045c-59a9-ae69-4b115f606d39', 'lisbon/tram-28', 'lisbon', 'Tram 28 is a sight, not always a commute', 'The famous Tram 28 is often packed with visitors, with long queues at the end stops. It''s slow if you just need to get somewhere.', 'transport', 'Tram 28', 38.7139, -9.1334, null, null, 'Ride it early for the experience, and walk or use the metro for getting around.', null, 52),
  ('bde3dd28-23df-54a6-9ccc-2637fc77e418', 'istanbul/hagia-sophia', 'istanbul', 'Visitor arrangements at Hagia Sophia have changed', 'Hagia Sophia is a mosque again, and arrangements for foreign visitors have changed in recent years, including separate visitor routes and fees.', 'planning', 'Hagia Sophia', 41.0086, 28.9802, null, null, 'Check the current visitor rules before you go rather than relying on older guides.', null, 53),
  ('c0e7474e-0c51-514d-bfde-4dc8a729129d', 'tromso/polar-night', 'tromso', 'Polar night means little daylight and real cold', 'For several weeks in winter the sun doesn''t rise above the horizon in Tromsø. Snowy, icy streets are normal.', 'packing', 'Fjellheisen viewpoint', 69.6385, 18.9822, null, null, 'Pack thermal layers and shoe grips, and plan daytime trips around the short twilight.', null, 54),
  ('daf58fa4-5fd9-596d-8a1d-6cf9f09a8137', 'kyoto/buses', 'kyoto', 'City buses can be slower than walking', 'Kyoto''s buses get very crowded around major sights, and full buses sometimes pass stops. Trains and subways are often quicker.', 'transport', 'Kyoto Station bus terminal', 34.9858, 135.7588, null, null, 'Use trains where possible and group sights by area.', null, 55),
  ('dc4fb37c-200e-560f-a999-245d4b301e96', 'bangkok/closed-today', 'bangkok', 'Be wary of "it''s closed today" approaches', 'A well-known approach near major sights is a friendly stranger saying the site is closed, then suggesting another tour. Usually the site is open.', 'safety', 'Grand Palace area', 13.7515, 100.4927, null, null, 'Check opening times at the official entrance yourself.', null, 56),
  ('830ff2e7-ff2f-5482-8651-c23718cbd172', 'ubud/monkey-forest', 'ubud', 'Monkeys will grab loose things', 'The monkeys in Ubud''s forest sanctuary are used to people and quick to grab sunglasses, food and anything dangling from a bag.', 'safety', 'Sacred Monkey Forest Sanctuary', -8.5188, 115.2585, null, null, 'Put loose items away before entering and don''t carry food.', null, 57),
  ('922d862c-9f67-57fd-82b9-c4455461f2a6', 'ha-long-bay/weather-cancellations', 'ha-long-bay', 'Storms can cancel cruises', 'Cruises on the bay are suspended when storms approach, which is most common in the typhoon months of summer and early autumn.', 'weather', 'Ha Long Bay', 20.9101, 107.1839, null, null, 'Read the cancellation and refund terms before booking, and keep a flexible day.', null, 58),
  ('6715ec0e-ce88-5a69-9501-21bcb2b563e1', 'siem-reap/upper-level-dress', 'siem-reap', 'Angkor Wat''s upper level has a dress code', 'Visitors to the upper level of Angkor Wat need covered shoulders and knees. People in shorts or tank tops can''t go up.', 'local_customs', 'Angkor Wat', 13.4125, 103.867, null, null, 'Dress modestly on the day you visit Angkor Wat.', null, 59),
  ('1d66ea3d-119f-50f0-8072-9ce999e9e42d', 'lukla/flight-delays', 'lukla', 'Lukla flights wait for the weather', 'Flights to and from Lukla depend on clear mountain weather and are often delayed or cancelled, sometimes for days.', 'planning', 'Lukla airport', 27.6869, 86.7298, null, null, 'Build buffer days into an Everest trek before your international flight home.', null, 60),
  ('6b4970cb-b14b-541f-8da0-76f27203b993', 'seoul/palace-tuesday', 'seoul', 'Gyeongbokgung closes on Tuesdays', 'Gyeongbokgung Palace is closed on Tuesdays, while some of Seoul''s other palaces close on Mondays.', 'planning', 'Gyeongbokgung Palace', 37.5796, 126.977, null, null, 'Check each palace''s closing day before planning a palace day.', null, 61),
  ('3f05a805-6529-578b-8dde-f57f26ad170f', 'dubai/ramadan', 'dubai', 'Be considerate during Ramadan', 'During Ramadan many people fast from dawn to sunset, and opening hours change. Visitors are expected to be respectful in public.', 'local_customs', 'Al Fahidi', 25.2637, 55.2972, null, null, 'Check opening hours and be discreet about eating and drinking in public during fasting hours.', null, 62),
  ('73b623b9-4593-59d6-8ac3-fffbd64a9c80', 'beijing/great-wall-section', 'beijing', 'Choose your Great Wall section on purpose', 'The Great Wall sections near Beijing differ a lot in crowds, restoration and steepness. The most famous section is also the busiest.', 'planning', 'Mutianyu Great Wall', 40.4319, 116.5704, null, null, 'Pick a section that matches how much crowd and climbing you want.', null, 63),
  ('256d6030-eb84-5eba-8c5d-f4476ad2e143', 'new-york-city/tipping', 'new-york-city', 'Budget for tips and sales tax', 'Menu prices in the US usually exclude sales tax, and tipping at sit-down restaurants is expected. The final bill can be noticeably higher than the menu suggested.', 'costs', 'Manhattan', 40.7831, -73.9712, null, null, 'Add tax and tip to your daily food budget.', null, 64),
  ('3ce2d4e1-71bf-57f3-80c8-94324ed1784e', 'banff/park-pass', 'banff', 'Stopping in the park needs a pass', 'A Parks Canada pass is needed to stop anywhere in Banff National Park, including the town.', 'costs', 'Banff Avenue', 51.1774, -115.5716, null, null, 'Buy the pass for the number of days you''ll be in the park.', null, 65),
  ('b0cba7a8-a926-5d61-8e3b-8ce6c95aba14', 'mexico-city/teotihuacan', 'mexico-city', 'Go to Teotihuacan early', 'Teotihuacan has very little shade and the sun is strong. Crowds and heat both build from late morning.', 'planning', 'Teotihuacan', 19.6925, -98.8438, null, null, 'Arrive at opening time with sun protection and water.', null, 66),
  ('e14ddb9d-36da-50eb-8f4d-185fbb1cabf1', 'machu-picchu/timed-circuits', 'machu-picchu', 'Tickets are timed and tied to circuits', 'Entry to Machu Picchu is limited per day, with set entry times and fixed walking circuits. Hikes such as Huayna Picchu need separate tickets.', 'planning', 'Machu Picchu citadel', -13.1631, -72.545, null, null, 'Book the ticket and train together, well in advance.', null, 67),
  ('d9ab8f2f-63b3-5163-a3a7-bea2252c69ca', 'rio-de-janeiro/beach-valuables', 'rio-de-janeiro', 'Take little to the beach', 'Unattended bags and phones on busy beaches are easy to lose. Locals typically bring very little.', 'safety', 'Copacabana', -22.9711, -43.1822, null, null, 'Bring only what you need and keep it with you.', null, 68),
  ('4f115587-29a1-50d4-8a13-2578a916c9de', 'el-chalten/cash', 'el-chalten', 'Bring cash into the village', 'El Chaltén is remote, and its few ATMs can run out of cash in busy periods. Card acceptance isn''t universal.', 'costs', 'El Chaltén', -49.3315, -72.8863, null, null, 'Arrive with enough cash for your stay.', null, 69),
  ('60a48bc3-8f6e-5b39-b3f7-a0f53736dabf', 'galapagos/wildlife-distance', 'galapagos', 'Keep your distance from wildlife', 'Animals in the Galápagos are often unafraid of people, but park rules require visitors to keep a set distance and never touch or feed them.', 'local_customs', 'Tortuga Bay', -0.7608, -90.333, null, null, 'Follow your guide''s lead and keep back.', null, 70),
  ('08b7d673-3bc3-501e-a680-b14ecdec713d', 'marrakech/agree-prices', 'marrakech', 'Agree prices before services', 'In the square and souks, prices for photos with performers, henna or rides are rarely fixed. Disagreements usually happen when nothing was agreed first.', 'costs', 'Jemaa el-Fna', 31.6258, -7.9891, null, null, 'Settle the price before accepting any service.', null, 71),
  ('f4caa286-dc4c-56bb-8c76-1c8dd2e46bcc', 'cape-town/hiking-not-alone', 'cape-town', 'Hike popular trails in company', 'Local advice for Table Mountain and Lion''s Head is to hike in groups, stay on busy trails and avoid going out late.', 'safety', 'Lion''s Head', -33.9353, 18.3893, null, null, 'Hike with others in daylight and tell someone your route.', null, 72),
  ('06a084be-cb15-5612-94e3-bc9cf38f2cc7', 'stone-town/modest-dress', 'stone-town', 'Dress modestly in town', 'Zanzibar is largely conservative. Beachwear is fine on the beach but out of place in Stone Town''s streets.', 'local_customs', 'Stone Town', -6.1659, 39.2026, null, null, 'Cover shoulders and knees when walking around town.', null, 73),
  ('d62e2bf3-808d-50a7-9d19-d4745fe6541e', 'sydney/uv', 'sydney', 'The sun burns fast', 'UV levels in Australia are high, and people burn quickly even on mild or cloudy days.', 'packing', 'Sydney Harbour', -33.8568, 151.2153, null, null, 'Use sunscreen, a hat and sunglasses every day.', null, 74),
  ('de29dbc4-f5a6-50a6-b71d-f4974f2feb66', 'queenstown/weather', 'queenstown', 'Mountain weather changes quickly', 'Weather in the Southern Alps can shift from sun to cold rain within hours, even in summer.', 'weather', 'Ben Lomond track', -45, 168.6333, null, null, 'Carry warm and waterproof layers on any hike.', null, 75),
  ('0909c9d2-e89a-5d9c-b546-ec2b823a97c2', 'rome/colosseum-timed', 'rome', 'Colosseum tickets are timed', 'Entry to the Colosseum works on timed tickets, and popular slots sell out in high season. Turning up hoping to buy at the gate often ends in disappointment.', 'planning', 'Colosseum', 41.8902, 12.4922, null, null, 'Book the official ticket ahead and arrive a little before your slot for security.', null, 76),
  ('4cbc2254-79ae-58dc-a984-9848a2d4312f', 'edinburgh/august-festival', 'edinburgh', 'August is festival month', 'In August the Edinburgh festivals fill the city. Rooms book out months ahead and prices rise sharply.', 'planning', 'Royal Mile', 55.9502, -3.1875, null, null, 'Book well ahead for August, or visit another month for a quieter city.', null, 77),
  ('8de0ee87-e123-5446-9864-9dea7bbae5d6', 'vik/winter-daylight', 'vik', 'Winter daylight is short', 'In midwinter there are only a few hours of daylight in southern Iceland, and storms can close the ring road.', 'weather', 'Vík', 63.4186, -19.006, null, null, 'Plan shorter driving days in winter and check road and weather warnings each morning.', null, 78),
  ('63e5d70d-e480-5448-8310-b968626b6db5', 'kyoto/gion-lanes', 'kyoto', 'Some Gion lanes are private', 'Some side streets in Gion are private roads where photography is restricted, and residents have asked visitors not to follow or photograph geiko and maiko.', 'local_customs', 'Gion', 35.0037, 135.7788, null, null, 'Follow the signs and never block or photograph people without consent.', null, 79),
  ('dabd89b3-2bf4-592e-9843-ac08c2e4120f', 'chiang-mai/burning-season', 'chiang-mai', 'Late dry season can be very smoky', 'From late winter into spring, crop and forest burning can leave Chiang Mai with heavy smoke and poor air quality. Mountain views disappear in the haze.', 'weather', 'Doi Suthep', 18.8048, 98.9216, null, null, 'Check air-quality readings before booking for that season.', null, 80),
  ('00324277-c7cb-5e2c-9e37-dfbb7e0d0edd', 'ubud/temple-sarong', 'ubud', 'Temples ask for a sarong', 'Balinese temples expect visitors to wear a sarong and sash. Many lend or rent them at the entrance.', 'local_customs', 'Tirta Empul', -8.4152, 115.3153, null, null, 'Bring your own sarong if you''ll visit several temples.', null, 81),
  ('876a2e2d-27d2-5c26-9516-68f5d32abdfc', 'beijing/payments', 'beijing', 'Set up mobile payments before you go', 'Mobile payment apps are used almost everywhere in China, and some smaller places don''t take foreign cards.', 'costs', 'Beijing', 39.9042, 116.4074, null, null, 'Link a card to a supported payment app before arrival and carry some cash.', null, 82),
  ('ca2b12c9-7646-5f7b-95f6-c27c1153e894', 'grand-canyon-south-rim/down-is-easy', 'grand-canyon-south-rim', 'Hiking down is the easy half', 'Trails into the canyon start with the descent, so it''s easy to go too far. The climb back out is steep and much hotter, especially in summer.', 'activity', 'Bright Angel Trailhead', 36.0576, -112.1435, null, null, 'Turn around well before you feel tired, and carry plenty of water and salty snacks.', null, 83),
  ('dafa0d26-0cbb-5f80-9cd3-87170563c01f', 'machu-picchu/bus-queue', 'machu-picchu', 'The bus from Aguas Calientes has queues', 'Buses up to the citadel start early, and morning queues can be long. Missing your entry time can be a problem.', 'transport', 'Aguas Calientes', -13.1547, -72.5254, null, null, 'Get to the bus stop well before your entry slot.', null, 84),
  ('bce5944d-305c-55d1-8711-fad04138487d', 'cairns/stinger-season', 'cairns', 'Wear a stinger suit in stinger season', 'Dangerous jellyfish are more common in tropical waters during the warmer months. Reef operators provide full-body suits.', 'safety', 'Great Barrier Reef pontoon', -16.75, 146, null, null, 'Wear the suit and swim only where operators and signs say it''s safe.', null, 85),
  ('cc66b0a5-2481-58f3-9510-655d2fe0fe7a', 'venice/access-fee', 'venice', 'Day visitors may need to pay an access fee', 'Venice has introduced an access fee for day-trippers on selected busy dates. Overnight guests are usually exempt but still need to register.', 'costs', 'Santa Lucia station', 45.4412, 12.3212, null, null, 'Check the city''s official calendar for fee days before a day trip.', null, 86),
  ('204134a0-3936-5784-8c02-39e42a26ddc4', 'edinburgh/four-seasons', 'edinburgh', 'Pack layers for any month', 'Edinburgh''s weather can change several times a day, and the top of Arthur''s Seat is windy even in summer.', 'packing', 'Arthur''s Seat', 55.9441, -3.1618, null, null, 'Carry a waterproof jacket and a warm layer whatever the forecast says.', null, 87),
  ('e862b01b-4770-54cc-865e-437c5481aa99', 'tokyo/ic-card', 'tokyo', 'Get an IC card on day one', 'Rechargeable IC cards work across Tokyo''s trains, subways and buses, and in many convenience stores. Buying single tickets for every ride is slow.', 'transport', 'Shinjuku Station', 35.6896, 139.7006, null, null, 'Set up an IC card or a mobile version as soon as you arrive.', null, 88),
  ('0f411cc1-2b17-52e0-a34b-764a309650d0', 'grand-canyon-south-rim/north-rim', 'grand-canyon-south-rim', 'The North Rim is seasonal and far away', 'The North Rim is open only part of the year and is a long drive around from the South Rim, not a quick hop across.', 'planning', 'South Rim Village', 36.0544, -112.1401, null, null, 'Treat the two rims as separate trips.', null, 89),
  ('7a96a9d1-ecf8-5282-b37d-b67c1d0614c4', 'uluru/no-climb', 'uluru', 'Uluru is not climbed', 'Climbing Uluru has been banned since 2019 out of respect for its traditional owners. Some sites around the base also ask visitors not to take photos.', 'local_customs', 'Uluru base walk', -25.3444, 131.0369, null, null, 'Walk the base instead and follow the signs about photography.', null, 90),
  ('d2757bc3-ca5f-5732-b3ab-1da92aaf3aab', 'venice/luggage-bridges', 'venice', 'Every bridge has steps', 'Almost every route through Venice crosses stepped bridges, and there are no taxis on land. A big suitcase becomes something to haul up and down dozens of times.', 'accessibility', 'Rialto Bridge', 45.438, 12.3359, null, null, 'Pack light and use the vaporetto stop closest to your stay.', null, 91),
  ('12d14f57-3f17-5c60-acf9-d22a48b77e67', 'tokyo/bins', 'tokyo', 'Public bins are rare', 'Tokyo''s streets are very clean but have few public rubbish bins. People carry their rubbish until they find a bin, often at a convenience store.', 'local_customs', 'Shibuya', 35.658, 139.7016, null, null, 'Keep a small bag for your rubbish.', null, 92),
  ('e9925ddd-4c7f-5b58-afc5-801f0ccd4840', 'yosemite-valley/reservations', 'yosemite-valley', 'Check for entry reservations', 'In some recent seasons Yosemite has required advance reservations to drive into the park at busy times. The rules have changed from year to year.', 'planning', 'Yosemite Valley', 37.7456, -119.5936, null, null, 'Check the National Park Service website for your dates before you travel.', null, 93),
  ('310db8ae-f6d3-5444-8827-af9fa84a7371', 'uluru/heat-flies', 'uluru', 'Pack for heat and flies', 'Summer days in the Red Centre are very hot, and bush flies are persistent.', 'packing', 'Kata Tjuta', -25.3, 130.7333, null, null, 'Walk early, carry lots of water, and pack a fly net.', null, 94),
  ('1248f469-48b4-5aca-a52c-4ed696480b24', 'yosemite-valley/tioga-road', 'yosemite-valley', 'Tioga Road closes in winter', 'The high Tioga Road across the park closes for snow, usually from late autumn until late spring or early summer.', 'weather', 'Tioga Road', 37.8746, -119.4246, null, null, 'Don''t plan a route through the high country outside summer without checking it''s open.', null, 95)
) as v(id, seed_key, destination_slug, title, body, category, place_name, latitude, longitude,
       travel_month, challenge, lesson, advice, ord)
join public.destinations d on d.slug = v.destination_slug
on conflict (id) do update set
  title = excluded.title,
  body = excluded.body,
  category = excluded.category,
  place_name = excluded.place_name,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  travel_month = excluded.travel_month,
  challenge = excluded.challenge,
  lesson = excluded.lesson,
  advice = excluded.advice
where s.source = 'editorial'
  and (s.title, s.body, s.category, s.place_name, s.latitude, s.longitude,
       s.travel_month, s.challenge, s.lesson, s.advice)
      is distinct from
      (excluded.title, excluded.body, excluded.category, excluded.place_name,
       excluded.latitude, excluded.longitude, excluded.travel_month,
       excluded.challenge, excluded.lesson, excluded.advice);

commit;
